INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7736630, 1275520, 29535, '<td valign="top">I love what you''ve done with this shot! So unique. And I''m giving a bonus point for what I''m pretty sure is a reference to the 90s video game which shares this POV and somewhat the aesthetic (if I''m wrong here, google a screenshot of it as the resemblance is striking!) Great job, this is what free studies are all about.</td>', 'I love what you''ve done with this shot! So unique. And I''m giving a bonus point for what I''m pretty sure is a reference to the 90s video game which shares this POV and somewhat the aesthetic (if I''m wrong here, google a screenshot of it as the resemblance is striking!) Great job, this is what free studies are all about.', '2023-01-15 04:10:01.000000', NULL, 1),
(7736641, 1275539, 29535, '<td valign="top">It''s clear this location is a favourite of yours and I''m starting to understand why. So much variety and inspiration from just one spot - this beach is clearly an important muse for you. For this shot I have to say it''s my favourite so far. I usually don''t love people in landscapes and yet here they add such a unique dynamic. All silhouetted, mostly paired off. Their shadows make them seem almost alien. Their composition is almost too perfect to be random, following the same lines as the sea and the shore. What a great image, probably the most interesting and inspiring since I came back!<br/> <br/>EDIT You know I finally get what this reminds me of - the work of L.S. Lowry and his famous matchstick men figures in his paintings. I could spend ages looking at each of these little silhouettes and figuring out what they''re doing. It''s like a Where''s Wally of different activities. Look hard you can see surfers, photographers, couples with dogs, someone taking a selfie, I could look at this all day :D</td>', 'It''s clear this location is a favourite of yours and I''m starting to understand why. So much variety and inspiration from just one spot - this beach is clearly an important muse for you. For this shot I have to say it''s my favourite so far. I usually don''t love people in landscapes and yet here they add such a unique dynamic. All silhouetted, mostly paired off. Their shadows make them seem almost alien. Their composition is almost too perfect to be random, following the same lines as the sea and the shore. What a great image, probably the most interesting and inspiring since I came back! EDIT You know I finally get what this reminds me of - the work of L.S. Lowry and his famous matchstick men figures in his paintings. I could spend ages looking at each of these little silhouettes and figuring out what they''re doing. It''s like a Where''s Wally of different activities. Look hard you can see surfers, photographers, couples with dogs, someone taking a selfie, I could look at this all day :D', '2023-01-15 10:32:55.000000', NULL, 1),
(7736646, 1275530, 29535, '<td valign="top">Wonderful image of a fantastic skyline. It''s a shame it couldn''t/wasn''t used for the Urban Landscape''s challenge as it would have scored highly there I think! But it''s also a great image and one of the stronger of the free study. Well done!</td>', 'Wonderful image of a fantastic skyline. It''s a shame it couldn''t/wasn''t used for the Urban Landscape''s challenge as it would have scored highly there I think! But it''s also a great image and one of the stronger of the free study. Well done!', '2023-01-15 13:00:34.000000', NULL, 1),
(7736647, 1275541, 29535, '<td valign="top">Right up my street and I love what you''ve done with the edit. Looks like an oil painting :)</td>', 'Right up my street and I love what you''ve done with the edit. Looks like an oil painting :)', '2023-01-15 13:00:57.000000', NULL, 1),
(7736648, 1275545, 29535, '<td valign="top">We don''t see enough candid shots on this site, bonus point for this on top of an interesting subject.</td>', 'We don''t see enough candid shots on this site, bonus point for this on top of an interesting subject.', '2023-01-15 13:00:59.000000', NULL, 1),
(7736649, 1275513, 29535, '<td valign="top">Just epic. I would love to know the steps involved in getting this so sharp and dramatic. Looks gorgeous and reminds me of home!</td>', 'Just epic. I would love to know the steps involved in getting this so sharp and dramatic. Looks gorgeous and reminds me of home!', '2023-01-15 13:01:21.000000', NULL, 1),
(7736650, 1275282, 29535, '<td valign="top">I keep coming back to this which alone makes it worth a little bump up. Simple but elegant and outside the box, and I love textured photos even if sometimes they break a lot of the ''rules'' of ''engaging photography''. What I love here is you''ve managed to adhere to those rules with the unusual plane of focus and in turn created quite an ethereal and unusual image. Love the colours too.</td>', 'I keep coming back to this which alone makes it worth a little bump up. Simple but elegant and outside the box, and I love textured photos even if sometimes they break a lot of the ''rules'' of ''engaging photography''. What I love here is you''ve managed to adhere to those rules with the unusual plane of focus and in turn created quite an ethereal and unusual image. Love the colours too.', '2023-01-15 13:02:46.000000', NULL, 1),
(7736651, 1275373, 29535, '<td valign="top">I have no idea what I''m looking at but I feel this deserves a bump as the second time round it stil has something special to me.</td>', 'I have no idea what I''m looking at but I feel this deserves a bump as the second time round it stil has something special to me.', '2023-01-15 13:03:07.000000', NULL, 1),
(7736652, 1275523, 29535, '<td valign="top">Wonderful colours and technique.</td>', 'Wonderful colours and technique.', '2023-01-15 13:04:08.000000', NULL, 1),
(7736653, 1275512, 29535, '<td valign="top">This is quirky and technically flawless, with wonderful colouring on the edit. I''m not quite sure what I''m looking at or why, which stops me giving it among the higher marks, but the contrast is definitely pleasing and I''d love to see more in this style.</td>', 'This is quirky and technically flawless, with wonderful colouring on the edit. I''m not quite sure what I''m looking at or why, which stops me giving it among the higher marks, but the contrast is definitely pleasing and I''d love to see more in this style.', '2023-01-15 13:05:24.000000', NULL, 1),
(7736725, 1275113, 114285, '<td valign="top">Another extremely gorgeous shot from <img border="0" src="https://www.dpchallenge.com/images/user_icon/21.gif" xalt="'' . substr(''https://www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''https://www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''"/> <a href="https://www.dpchallenge.com/profile.php?USER_ID=29535" rel="nofollow" target="_blank">Rankles</a> I''m guessing. So peaceful, makes me want to be there. The soft wispy clouds and the tree lined background is just perfect. Then there''s the lone fisherman who seems to have paused momentarily in time. A truly wonderful image. Should do well for you.</td>', 'Another extremely gorgeous shot from  Rankles I''m guessing. So peaceful, makes me want to be there. The soft wispy clouds and the tree lined background is just perfect. Then there''s the lone fisherman who seems to have paused momentarily in time. A truly wonderful image. Should do well for you.', '2023-01-17 01:32:07.000000', NULL, 1),
