(7737010, 1275430, 63398, '<td valign="top">A truly amazing capture! 8</td>', 'A truly amazing capture! 8', '2023-01-21 14:31:42.000000', NULL, 1),
(7737011, 1275523, 63398, '<td valign="top">My pick for the winner. The DOF, clarity, attention to detail, tonal quality, composition.......this has it all going on and is most pleasing as well. It makes me want to know the story. 9</td>', 'My pick for the winner. The DOF, clarity, attention to detail, tonal quality, composition.......this has it all going on and is most pleasing as well. It makes me want to know the story. 9', '2023-01-21 14:38:39.000000', NULL, 1),
(7737012, 1275547, 63398, '<td valign="top">The title really drives this for me on multiple levels. A really interesting setting. I''m truly unsure how it came to be, but in my mind there was a serious crash and burn. I see the hawk as having fallen to earth from misjudging the weight of the hare yet refusing to release it even at the cost of his own life. Icarus, indeed. 8</td>', 'The title really drives this for me on multiple levels. A really interesting setting. I''m truly unsure how it came to be, but in my mind there was a serious crash and burn. I see the hawk as having fallen to earth from misjudging the weight of the hare yet refusing to release it even at the cost of his own life. Icarus, indeed. 8', '2023-01-21 14:42:55.000000', NULL, 1),
(7737013, 1275113, 63398, '<td valign="top">I very much like this composition. Subjectively, the blue cast seems......off a tad, but if ti was like that, so be it. 6</td>', 'I very much like this composition. Subjectively, the blue cast seems......off a tad, but if ti was like that, so be it. 6', '2023-01-21 14:48:52.000000', NULL, 1),
